 }

-NS_IMETHODIMP EwsFolder::HandleDownloadedMessages(
-    nsTArray<nsMsgKey> const& msgs) {
+NS_IMETHODIMP EwsFolder::HandleDownloadedMessages() {
   // There may be filters that were waiting for the full message.
   PerformFiltering();
   return NS_OK;
diff --git a/mailnews/protocols/ews/src/EwsMessageChannel.cpp b/mailnews/protocols/ews/src/EwsMessageChannel.cpp
index ff6afd2d69f..9903b332f26 100644
--- a/mailnews/protocols/ews/src/EwsMessageChannel.cpp
+++ b/mailnews/protocols/ews/src/EwsMessageChannel.cpp
@@ -319,11 +319,11 @@ NS_IMETHODIMP EwsMessageChannel::AsyncOpen(nsIStreamListener* aListener) {
   //       local copy of this message?
   return EwsFetchMsgsToOffline(
       folder, {msgKey},
-      [self = RefPtr(this), ewsFolder, msgKey,
+      [self = RefPtr(this), ewsFolder,
        listener = nsCOMPtr(aListener)](nsresult status) {
         if (NS_SUCCEEDED(status)) {
           // Let the folder know a message has been downloaded.
-          ewsFolder->HandleDownloadedMessages({msgKey});
+          ewsFolder->HandleDownloadedMessages();

           // Yay! We've now got the offline copy in the store.
           // Can start streaming it out now....
diff --git a/mailnews/protocols/ews/src/IEwsFolder.idl b/mailnews/protocols/ews/src/IEwsFolder.idl
index 2e1688eb57a..1ff39b10bad 100644
--- a/mailnews/protocols/ews/src/IEwsFolder.idl
+++ b/mailnews/protocols/ews/src/IEwsFolder.idl
@@ -43,20 +43,20 @@ void copyItemsOnSameServer(
     in IEwsFolderOperationListener listener);

 /**
- * Tell the folder that the specified messages have been downloaded for
+ * Tell the folder that some messages have been downloaded for
  * offline use and are now in the local message store.
  *
  * IMAP and NNTP handle downloading messages directly in the folder code,
  * but EWS farms the work out to folder-external code
  * (EwsFetchMsgsToOffline()), so this call is needed to tell the folder
- * to perform any actions it might need to do in response (i.e. applying
+ * to perform any actions it might need to do in response (e.g. applying
  * message filters which require the full message).
  *
  * Ultimately it'd be nice to have IMAP and NNTP share the same
  * offline-download path as EWS, and at that point this call would
- * be promoted up to the nsIMsgFolder interface.
+ * be removed in favour of a more general mechanism.
  */
-void handleDownloadedMessages(in Array<nsMsgKey> msgs);
+void handleDownloadedMessages();
 };

